 private static void validateIndexTaxonomy(Path db,MaltTaxonomy tree)throws IOException {
  var references=org.jlinalg.workflow.NfcoreEagerScreeningReads.references(db.resolve("ref.db"),db.resolve("ref.idx"),db.resolve("ref.inf"),10000000,100000000000L);
  if(Files.size(db.resolve("taxonomy.idx"))!=18L+4L*references.size())throw new IOException("Complete index taxonomy count differs");
  try(var in=new java.io.DataInputStream(Files.newInputStream(db.resolve("taxonomy.idx")))) {
   if(!Arrays.equals(in.readNBytes(14),"MATaxonomyV1.1".getBytes(StandardCharsets.US_ASCII))||in.readInt()!=references.size())throw new IOException("Unsupported/incomplete taxonomy index");
   for(String name:references.keySet()){int taxon=in.readInt();var match=java.util.regex.Pattern.compile("\\|tax\\|([0-9]+)\\|?$").matcher(name);if(taxon<=0||!tree.contains(taxon)||!match.find()||Integer.parseInt(match.group(1))!=taxon)throw new IOException("Unclassified, unknown or inconsistent complete reference taxonomy: "+name+"; original0.5.2 accession mapping can exit zero without classifying references. Supply an explicitly declared validated index or skip dependent analysis.");}
   if(in.read()!=-1)throw new IOException("Trailing taxonomy index data");
  }
 }
 private static void validateQueries(Path query,Capacities limits)throws IOException {var names=new HashSet<String>();long bases=0;try(var r=new FastqIO.Reader(query)){FastqIO.Read row;while((row=r.next())!=null){if(!names.add(row.header().substring(1).split("\\s+",2)[0]))throw new Unavailable("Nonunique query identity cannot be cross-checked; no representative is selected");bases=Math.addExact(bases,row.sequence().length());if(names.size()>limits.queries()||bases>limits.queryBases())throw new IOException("Complete query population exceeds declared capacity");}}}
 private static Map<String,Object> scientific(Path runtime,Path query,Path db,Path sam,Path rma,Parameters p,Capacities limits)throws IOException {return scientific(runtime,query,db,sam,rma,p,limits,new Malt052Reassignment.Session(runtime,new MaltTaxonomy.Limits(100000000,3000000,1024)));}
