 private static long alignedFastaAndRawReads(Path runtime,Path query,Path fasta,Path rma,MaltAlignmentAudit.Result audit,Capacities limits)throws IOException {
  var sequences=new HashMap<String,String>();try(var reader=new FastqIO.Reader(query)){FastqIO.Read row;while((row=reader.next())!=null)if(sequences.putIfAbsent(row.header().substring(1).split("\\s+",2)[0],dna5(row.sequence()))!=null)throw new IOException("Nonunique complete query name");}
  var seen=new HashSet<String>();try(var reader=new java.io.BufferedReader(new java.io.InputStreamReader(new java.util.zip.GZIPInputStream(Files.newInputStream(fasta)),StandardCharsets.UTF_8))) {
   String line,name=null;var sequence=new StringBuilder();while((line=reader.readLine())!=null){if(line.startsWith(">")){if(name!=null)checkFasta(sequences,seen,name,sequence.toString());name=line.substring(1).split("\\s+",2)[0];sequence.setLength(0);}else{if(name==null||sequence.length()+line.length()>limits.queryBases())throw new IOException("Unassessable/over-capacity complete aligned FASTA");sequence.append(line);}}if(name!=null)checkFasta(sequences,seen,name,sequence.toString());
  }
  if(!seen.equals(audit.counts().keySet()))throw new IOException("Complete aligned FASTA/SAM identities differ");var rawNames=new HashSet<String>();
  var raw=Malt052RmaReader.read(runtime,rma,limits.rma(),read->{String expected=sequences.get(read.name());if(expected==null||!rawNames.add(read.name())||read.length()!=expected.length()||!expected.equals(read.sequence())||read.totalMatches()!=audit.counts().getOrDefault(read.name(),0))throw new java.io.UncheckedIOException(new IOException("Complete raw RMA/input identities, lengths, sequences or match counts differ: "+read.name()));});
  if(raw.availableMatches()!=raw.storedMatches()||raw.storedMatches()!=audit.alignments())throw new IOException("Incomplete original raw RMA match population");return seen.size();
 }
 private static void checkFasta(Map<String,String> expected,Set<String> seen,String name,String sequence)throws IOException {if(sequence.isEmpty()||!seen.add(name)||!Objects.equals(expected.get(name),sequence))throw new IOException("Aligned FASTA record differs from complete source DNA5 query: "+name);}
 private static String dna5(String input){var out=new StringBuilder(input.length());for(int i=0;i<input.length();i++)out.append(switch(input.charAt(i)){case 'A','a'->'A';case 'C','c'->'C';case 'G','g'->'G';case 'T','t','U','u'->'T';default->'N';});return out.toString();}
