 private static Map<String,NextflowFiles.Pin> database(Path db,long maximum)throws IOException {
  NextflowFiles.directory(db);var files=new TreeMap<String,NextflowFiles.Pin>();var tables=new TreeSet<Integer>();
  try(var rows=Files.list(db)){for(Path p:rows.toList()){String n=p.getFileName().toString();if(n.matches("(?:index|table)[0-9]+\\.(?:idx|db)")){if(n.startsWith("index")&&n.endsWith(".idx"))tables.add(Integer.valueOf(n.substring(5,n.length()-4)));}else if(!Set.of("ref.db","ref.idx","ref.inf","taxonomy.idx","taxonomy.tre","taxonomy.map").contains(n))throw new Unavailable("Unsupported taxonomy-only BlastN index member: "+n);if(files.size()>=10000)throw new IOException("Complete index member capacity exceeded");files.put(n,NextflowFiles.pin(p,maximum,()->{}));}}
  if(tables.isEmpty()||!files.keySet().containsAll(Set.of("ref.db","ref.idx","ref.inf","taxonomy.idx","taxonomy.tre","taxonomy.map")))throw new IOException("Incomplete taxonomy-only BlastN index");
  var expected=new HashSet<String>(Set.of("ref.db","ref.idx","ref.inf","taxonomy.idx","taxonomy.tre","taxonomy.map"));for(int i=0;i<tables.size();i++){if(!tables.contains(i))throw new IOException("Non-contiguous original seed-table indices");expected.add("index"+i+".idx");expected.add("table"+i+".idx");expected.add("table"+i+".db");}if(!files.keySet().equals(expected))throw new IOException("Incomplete/extra original seed-table parts");return Collections.unmodifiableMap(files);
 }
