 private static long number(Map<String,String> o,String n,long fallback,long low,long high)throws IOException {long value=o.containsKey(n)?Long.parseLong(o.get(n)):fallback;if(value<low||value>high)throw new IOException("Bounded complete capacity/integer required: "+n);return value;}
 private static double real(Map<String,String> o,String n,double fallback,double low,double high)throws IOException {double v=o.containsKey(n)?Double.parseDouble(o.get(n)):fallback;if(!Double.isFinite(v)||v<low||v>high)throw new IOException("Finite supported value required: "+n);return v;}
 private static boolean bool(Map<String,String> o,String n,boolean fallback)throws IOException {if(!o.containsKey(n))return fallback;if(!Set.of("true","false").contains(o.get(n)))throw new IOException("Literal true/false required: "+n);return Boolean.parseBoolean(o.get(n));}
 private static String choice(Map<String,String> o,String n,String fallback,Set<String> allowed)throws IOException {String v=o.getOrDefault(n,fallback);if(!allowed.contains(v))throw new IOException("Unsupported explicit choice for "+n);return v;}
